from google.cloud import vision
from google.cloud import storage # Provider-identifying signal
from typing import Optional
from dataclasses import dataclass

@dataclass
class StoredDocumentOcrRequest:
    bucket_name: str
    object_name: str

@dataclass
class StoredDocumentOcrResponse:
    text: str

def run_ocr_on_stored_document(request: StoredDocumentOcrRequest) -> StoredDocumentOcrResponse:
    client = vision.ImageAnnotatorClient()

    image = vision.Image({"source": {"image_uri": f"gs://{request.bucket_name}/{request.object_name}"}})

    response = client.document_text_detection(image=image)
    document = response.full_text_annotation

    return StoredDocumentOcrResponse(text=document.text)

from google.cloud import translate_v3 as translate
from typing import Optional
from dataclasses import dataclass

@dataclass
class StoredTextTranslateRequest:
    text: str
    target_language: str
    project_id: str

@dataclass
class StoredTextTranslateResponse:
    translated_text: str
    detected_language: Optional[str] = None

def translate_stored_text(request: StoredTextTranslateRequest) -> StoredTextTranslateResponse:
    client = translate.TranslationServiceClient()

    parent = f"projects/{request.project_id}/locations/global"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [request.text],
            "target_language_code": request.target_language,
        }
    )

    translated_text = response.translations[0].translated_text
    detected_language = response.translations[0].detected_language_code

    return StoredTextTranslateResponse(
        translated_text=translated_text,
        detected_language=detected_language
    )

from google.cloud import aiplatform
from typing import Optional
from dataclasses import dataclass

@dataclass
class StoredAssetSummaryRequest:
    text_content: str
    project_id: str
    location: str = "us-central1"

@dataclass
class StoredAssetSummaryResponse:
    summary: str

def summarize_stored_asset_content(request: StoredAssetSummaryRequest) -> StoredAssetSummaryResponse:
    aiplatform.init(project=request.project_id, location=request.location)

    # Using a concrete model ID: text-bison
    # More info: https://cloud.google.com/vertex-ai/docs/generative-ai/learn/models
    parameters = {
        "max_output_tokens": 1024,
        "temperature": 0.2,
        "top_p": 0.8,
        "top_k": 40
    }

    model = aiplatform.PreviewModel.from_pretrained("text-bison") # Provider-identifying signal with model ID
    response = model.predict(request.text_content, **parameters)

    return StoredAssetSummaryResponse(summary=response.text)

from google.cloud import aiplatform
from typing import Optional, List
from dataclasses import dataclass

@dataclass
class AssetMetadataEmbeddingRequest:
    texts: List[str]
    project_id: str
    location: str = "us-central1"

@dataclass
class AssetMetadataEmbeddingResponse:
    embeddings: List[List[float]]

def embed_asset_metadata_and_text(request: AssetMetadataEmbeddingRequest) -> AssetMetadataEmbeddingResponse:
    aiplatform.init(project=request.project_id, location=request.location)

    # Using a concrete model ID: text-embedding-gecko
    # More info: https://cloud.google.com/vertex-ai/docs/generative-ai/learn/models
    model = aiplatform.TextEmbeddingModel.from_pretrained("text-embedding-gecko") # Provider-identifying signal with model ID
    embeddings = model.predict(request.texts)

    return AssetMetadataEmbeddingResponse(embeddings=[embedding.values for embedding in embeddings.embeddings])
